mapper.select:
SELECT state_name FROM mk_journey_definition
WHERE tenant_id = #{tenantId} AND journey_id = #{journeyId} AND version_no = #{version}
FOR UPDATE

mapper.update:
UPDATE mk_journey_definition SET state_name = 'MIGRATED'
WHERE tenant_id = #{tenantId} AND journey_id = #{journeyId} AND version_no = #{version}
  AND state_name = 'MIGRATING'

mapper.select:
SELECT enrollment_id AS enrollmentId, snapshot_json AS snapshotJson, created_at AS createdAt
FROM mk_enrollment
WHERE tenant_id = #{tenantId} AND journey_id = #{journeyId} AND journey_version = #{version}
  AND subject_token = #{subjectToken} AND trigger_event_id = #{triggerEventId}

mapper.update:
UPDATE mk_enrollment
SET status_name = #{statusName}, current_node_id = #{currentNodeId}, snapshot_json = #{snapshotJson},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND enrollment_id = #{enrollmentId}

mapper.select:
SELECT snapshot_json FROM mk_enrollment
WHERE tenant_id = #{tenantId} AND enrollment_id = #{enrollmentId}
FOR UPDATE

SELECT snapshot_json AS snapshotJson, updated_at AS updatedAt
FROM mk_enrollment
WHERE tenant_id = #{tenantId}
AND status_name = #{statusName}
AND journey_id = #{journeyId}
ORDER BY updated_at DESC, enrollment_id
LIMIT #{limit}

SELECT snapshot_json FROM mk_enrollment
WHERE tenant_id = #{tenantId} AND journey_id = #{journeyId} AND journey_version = #{fromVersion}
  AND status_name IN ('RUNNING', 'WAITING') AND enrollment_id > #{afterEnrollmentId}
ORDER BY enrollment_id
LIMIT #{limit}
FOR UPDATE

mapper.update:
UPDATE mk_enrollment
SET journey_version = #{journeyVersion}, current_node_id = #{currentNodeId},
    snapshot_json = #{snapshotJson}, updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND enrollment_id = #{enrollmentId}

mapper.select:
SELECT COUNT(*) FROM mk_enrollment
WHERE tenant_id = #{tenantId} AND journey_id = #{journeyId} AND journey_version = #{version}
  AND status_name IN ('RUNNING', 'WAITING')

SELECT release_key_id AS releaseKeyId, manifest_json AS manifestJson, artifact_id AS artifactId,
       artifact_payload AS artifactPayload
FROM mk_journey_runtime_generation
WHERE tenant_id = #{tenantId} AND environment_name = #{environment} AND cell_id = #{cell}
  AND namespace_name = #{namespace} AND generation_no = #{generation}

SELECT desired_generation AS desiredGeneration, activation_sequence AS activationSequence,
       directive_signature AS directiveSignature
FROM mk_journey_runtime_slot
WHERE tenant_id = #{tenantId} AND environment_name = #{environment} AND cell_id = #{cell}
  AND namespace_name = #{namespace}
FOR UPDATE

mapper.update:
UPDATE mk_journey_runtime_slot
SET desired_generation = #{desiredGeneration}, activation_sequence = #{activationSequence},
    directive_signature = #{directiveSignature}, directive_json = #{directiveJson}, updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND environment_name = #{environmentName} AND cell_id = #{cellId}
  AND namespace_name = #{namespaceName}

UPDATE mk_journey_runtime_kill_switch
SET switch_sequence = #{switchSequence}, enabled_value = #{enabledValue}, reason_text = #{reasonText},
    directive_signature = #{directiveSignature}, directive_json = #{directiveJson}, updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND namespace_name = #{namespaceName}

mapper.select:
SELECT tenant_id AS tenantId, directive_json AS directiveJson
FROM mk_journey_runtime_kill_switch
WHERE namespace_name = #{namespace}

SELECT payload_hash AS payloadHash, event_type AS eventType
FROM mk_journey_output_receipt
WHERE source_topic = #{topic} AND source_partition = #{partition} AND source_offset = #{offset}

mapper.update:
UPDATE mk_enrollment
SET status_name = #{statusName}, current_node_id = #{currentNodeId}, snapshot_json = #{snapshotJson},
    projection_topic = #{projectionTopic}, projection_partition = #{projectionPartition},
    projection_offset = #{projectionOffset}, updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND enrollment_id = #{enrollmentId}

mapper.select:
SELECT journey_id AS journeyId, journey_version AS journeyVersion, subject_token AS subjectToken
FROM mk_enrollment
WHERE tenant_id = #{tenantId} AND enrollment_id = #{enrollmentId}

mapper.update:
UPDATE mk_journey_dispatch_position
SET last_sequence = last_sequence + 1, updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND enrollment_id = #{enrollmentId}

UPDATE mk_journey_dispatch_outbox
SET publish_attempts = #{attempts}, dead_lettered_at = #{deadLetteredAt}, last_error = #{error}
WHERE tenant_id = #{tenantId} AND outbox_id = #{outboxId}
  AND published_at IS NULL AND dead_lettered_at IS NULL

UPDATE mk_journey_dispatch_outbox
SET publish_attempts = #{attempts}, next_attempt_at = #{nextAttemptAt}, last_error = #{error}
WHERE tenant_id = #{tenantId} AND outbox_id = #{outboxId} AND published_at IS NULL
